// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/healthz", wrapper.Health)
	m.HandleFunc("GET "+options.BaseURL+"/v1/activation/totp", wrapper.GetTotpStatus)
	m.HandleFunc("POST "+options.BaseURL+"/v1/activation/totp", wrapper.StartTotpEnrollment)
	m.HandleFunc("POST "+options.BaseURL+"/v1/activation/totp/confirm", wrapper.ConfirmTotpEnrollment)
	m.HandleFunc("POST "+options.BaseURL+"/v1/certificates", wrapper.IssueCertificate)
	m.HandleFunc("GET "+options.BaseURL+"/v1/keys", wrapper.ListKeys)
	m.HandleFunc("POST "+options.BaseURL+"/v1/keys", wrapper.CreateKey)
	m.HandleFunc("GET "+options.BaseURL+"/v1/keys/capabilities", wrapper.GetKeyCapabilities)
	m.HandleFunc("GET "+options.BaseURL+"/v1/keys/{keyId}", wrapper.GetKey)
	m.HandleFunc("PATCH "+options.BaseURL+"/v1/keys/{keyId}", wrapper.RenameKey)
	m.HandleFunc("PATCH "+options.BaseURL+"/v1/keys/{keyId}/certificates/{certificateId}", wrapper.RenameCertificate)
	m.HandleFunc("GET "+options.BaseURL+"/v1/signatures/digest", wrapper.ListDigestSignatures)
	m.HandleFunc("POST "+options.BaseURL+"/v1/signatures/digest", wrapper.CreateDigestSignature)
	m.HandleFunc("GET "+options.BaseURL+"/v1/signatures/digest/{requestId}", wrapper.GetDigestSignature)
	m.HandleFunc("POST "+options.BaseURL+"/v1/signatures/digest/{requestId}/approve", wrapper.ApproveDigestSignature)
	m.HandleFunc("GET "+options.BaseURL+"/v1/signatures/p7m", wrapper.ListP7m)
	m.HandleFunc("POST "+options.BaseURL+"/v1/signatures/p7m", wrapper.UploadP7m)
	m.HandleFunc("GET "+options.BaseURL+"/v1/signatures/p7m/{jobId}", wrapper.GetP7m)
	m.HandleFunc("POST "+options.BaseURL+"/v1/signatures/p7m/{jobId}/approve", wrapper.ApproveP7m)
	m.HandleFunc("GET "+options.BaseURL+"/v1/signatures/p7m/{jobId}/download", wrapper.DownloadP7m)

	return m
}
